<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import Icon from './Icon.vue'
import type {QuotaState} from './types'
const props=defineProps<{quota:QuotaState;busy:string}>()
const emit=defineEmits<{action:[method:string,params:Record<string,unknown>,message:string];draftChange:[dirty:boolean]}>()
const search=ref(''),checked=ref<string[]>([])
const drafts=ref<Record<string,{enabled:boolean;prompt:string}>>({}),baselines=ref<Record<string,{enabled:boolean;prompt:string}>>({})
const locked=computed(()=>props.quota.enabled||!!props.busy)
const rules=computed(()=>props.quota.continuation_rules || {})
const records=computed(()=>props.quota.choices.filter(c=>props.quota.config.threads[c.id]))
function dirty(id:string){const draft=drafts.value[id],saved=rules.value[id] || {enabled:false,prompt:''};return !!draft&&(draft.enabled!==saved.enabled||draft.prompt!==saved.prompt)}
watch(()=>props.quota.choices,()=>{for(const row of records.value){const saved=rules.value[row.id] || {enabled:false,prompt:''};const previous=baselines.value[row.id];if(!drafts.value[row.id]||(previous&&drafts.value[row.id].enabled===previous.enabled&&drafts.value[row.id].prompt===previous.prompt))drafts.value[row.id]={...saved};baselines.value[row.id]={...saved}}},{immediate:true,deep:true})
watch(()=>records.value.some(c=>dirty(c.id)),value=>emit('draftChange',value),{immediate:true})
watch(()=>props.quota.catalog?.items.map(c=>c.id).join('|'),()=>checked.value=[])
const attached=computed(()=>new Set(records.value.map(c=>c.id)))
watch(()=>records.value.map(c=>c.id).join('|'),()=>checked.value=checked.value.filter(id=>!attached.value.has(id)))
const stateNames:Record<string,string>={watching:'守护就绪',interrupt_pending:'等待中断确认',paused:'已中断 · 待恢复',paused_idle:'未完成 · 待恢复',resume_pending:'续聊结果待核实'}
const short=(id:string)=>id.length>18?id.slice(0,8)+'…'+id.slice(-6):id
function name(id:string){return props.quota.catalog?.items.find(c=>c.id===id)?.name || props.quota.choices.find(c=>c.id===id)?.name || short(id)}
function browse(cursor:string|null=null){emit('action','quota.threads.browse',{search:search.value,cursor},'已有对话列表已更新。')}
function save(id:string){const draft=drafts.value[id];emit('action','quota.continuation',{threadId:id,enabled:draft.enabled,prompt:draft.prompt},'此对话的续聊规则已保存。')}
</script>
<template><section class="existing-conversations"><section class="panel existing-browser"><div class="section-heading"><div><span class="eyebrow muted">EXISTING CONVERSATIONS</span><h3>接入已有对话</h3><p>选择一个或多个已有目标，接入时保留原对话 ID 与历史，不发送消息。</p></div><span class="badge subtle">最多 20 个／批</span></div><form class="conversation-search" @submit.prevent="browse()"><label class="sr-only" for="conversation-search">搜索已有对话</label><input id="conversation-search" v-model="search" maxlength="120" :disabled="!quota.connected||!!busy" placeholder="按对话标题搜索"><button class="btn secondary browse-conversations" :disabled="!quota.connected||!!busy" type="submit"><Icon name="refresh" :size="16"/>读取已有对话</button></form><div v-if="quota.catalog?.items.length" class="catalog-list"><label v-for="item in quota.catalog.items" :key="item.id" class="catalog-row" :class="{attached:attached.has(item.id)}"><input v-model="checked" type="checkbox" :value="item.id" :disabled="locked||attached.has(item.id)" :aria-label="`接入 ${item.name}`"><span class="catalog-title"><strong>{{ item.name }}</strong><small :title="item.cwd">{{ item.cwd || '未提供工作区' }}</small><code>{{ short(item.id) }}</code></span><span class="badge" :class="{success:attached.has(item.id)}">{{ attached.has(item.id)?'已接管':'待检查' }}</span></label></div><div v-else class="catalog-empty"><Icon name="layers" :size="24"/><span>{{ quota.connected?(quota.catalog?.updated?'当前搜索暂无结果':'点击读取，从已有对话中选择目标'):'连接 Codex 后读取已有对话' }}</span></div><div class="catalog-actions"><span>{{ checked.length }} 个已选<span v-if="locked"> · 关闭守护后可调整接入</span></span><div class="button-row"><button v-if="quota.catalog?.cursor" class="btn ghost" :disabled="!!busy" @click="browse(quota.catalog.cursor)">下一页</button><button class="btn primary attach-conversations" :disabled="locked||!checked.length||checked.length>20" @click="emit('action','quota.threads.attach',{ids:checked},'接入检查已完成，请核对每个目标的状态。')"><Icon name="link" :size="16"/>接入选中对话</button></div></div><div v-if="quota.last_attach?.attached.length" class="notice neutral attach-summary" role="status"><Icon name="check" :size="16"/>已接管 {{ quota.last_attach.attached.length }} 个目标，尚未发送续聊消息。</div><div v-for="failure in quota.last_attach?.failed || []" :key="failure.id" class="notice warning attach-failure" role="alert"><Icon name="info" :size="17"/><div><strong>{{ name(failure.id) }}</strong><p>{{ failure.reason }}</p></div></div></section>
<section class="panel continuation-targets"><div class="section-heading"><div><span class="eyebrow muted">PER CONVERSATION</span><h3>守护与续聊目标 <span class="count-badge">{{ records.length }}</span></h3><p>每段对话独立设置恢复内容；留空使用默认继续指令，已完成的回合自动跳过。</p></div><span class="badge subtle">{{ records.filter(c=>quota.config.threads[c.id]?.selected).length }} 个已选目标</span></div><div v-if="!records.length" class="catalog-empty"><Icon name="shield" :size="27"/><span>先接入一个已有对话，再为它设置守护与续聊。</span></div><div v-else class="continuation-list"><article v-for="thread in records" :key="thread.id" class="continuation-card"><header><label class="guard-target-check"><input type="checkbox" :checked="!!quota.config.threads[thread.id]?.selected" :disabled="!!busy" @change="emit('action','quota.select',{threadId:thread.id,selected:($event.target as HTMLInputElement).checked},'此对话的守护范围已更新。')"><span class="target-name"><strong>{{ thread.name }}</strong><code>{{ short(thread.id) }}</code></span></label><span class="badge">{{ !quota.config.threads[thread.id]?.selected?'未纳入守护':quota.turn_states?.[thread.id]==='completed'?'已完成 · 跳过恢复':stateNames[quota.config.threads[thread.id]?.state] || '等待状态' }}</span></header><p v-if="quota.config.threads[thread.id]?.control_error" class="target-error">{{ quota.config.threads[thread.id].control_error }}</p><details class="continuation-editor"><summary><span><Icon name="settings" :size="15"/>续聊规则<span class="badge subtle">{{ rules[thread.id]?.enabled?(rules[thread.id]?.prompt?'自定义':'默认继续'):'不自动续聊' }}</span></span><Icon name="down" :size="15"/></summary><div v-if="drafts[thread.id]" class="continuation-form"><label class="resume-enabled"><input v-model="drafts[thread.id].enabled" type="checkbox" :disabled="locked">额度满后，恢复这段未完成的对话</label><label class="field-label" :for="`resume-prompt-${thread.id}`">自定义续聊内容<span>可留空 · 最多 4000 字</span></label><textarea :id="`resume-prompt-${thread.id}`" v-model="drafts[thread.id].prompt" class="resume-prompt" rows="3" maxlength="4000" :disabled="locked||!drafts[thread.id].enabled" placeholder="留空时：继续本对话尚未完成的任务，核对已完成部分，避免重复操作。"></textarea><div class="rule-footer"><small>{{ quota.enabled?'关闭守护后可修改规则。':'只有开启上方自动恢复总开关，并保存此规则后，才会自动续聊。' }}</small><button class="btn secondary save-continuation" :data-thread="thread.id" :disabled="locked||!dirty(thread.id)" @click="save(thread.id)"><Icon name="check" :size="15"/>保存此对话规则</button></div></div></details></article></div><p class="continuation-note"><Icon name="info" :size="14"/>完成状态来自 Codex 回合状态。已完成的回合不发送自动消息；状态不明、结果未知或目标不可控时等待核实。</p></section></section></template>
<style scoped>
.existing-conversations{display:grid;gap:20px;min-width:0}.existing-browser,.continuation-targets{min-width:0}.conversation-search{display:flex;gap:12px;margin-bottom:18px}.conversation-search>input{flex:1;min-width:0;background:var(--surface-input);color:var(--text);border:1px solid var(--line);border-radius:10px;padding:11px 13px;font-size:12px}.catalog-list{display:grid;gap:8px;max-height:410px;overflow:auto;padding:2px}.catalog-row{display:flex;align-items:center;gap:13px;min-width:0;border:1px solid var(--line);border-radius:11px;padding:14px 15px;background:var(--surface-input);cursor:pointer;transition:background .25s,border-color .25s}.catalog-row:has(input:checked){border-color:var(--accent-strong);background:var(--accent-soft)}.catalog-row.attached{cursor:default}.catalog-row>input,.guard-target-check>input,.resume-enabled>input{width:16px;height:16px;flex-shrink:0;accent-color:var(--accent)}.catalog-title{display:grid;gap:5px;min-width:0;flex:1}.catalog-title strong,.target-name strong{font-size:12px;font-weight:550;line-height:1.8;color:var(--text);overflow-wrap:anywhere}.catalog-title small{font-size:10px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.catalog-title code,.target-name code{font:10px Consolas,monospace;color:var(--muted);overflow-wrap:anywhere}.catalog-actions{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-top:18px;color:var(--muted);font-size:11px}.catalog-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:13px;min-height:120px;padding:20px;color:var(--muted);font-size:12px;line-height:1.9;text-align:center}.catalog-empty svg{color:var(--accent);opacity:.7}.attach-summary,.attach-failure{margin-top:15px;font-size:12px}.attach-failure strong{font-size:12px;font-weight:550;overflow-wrap:anywhere}.attach-failure p{font-size:11px;margin-top:5px;overflow-wrap:anywhere}.continuation-list{display:grid;gap:13px}.continuation-card{border:1px solid var(--line);border-radius:12px;background:var(--surface-input);padding:16px;min-width:0}.continuation-card>header{display:flex;align-items:center;justify-content:space-between;gap:13px;flex-wrap:wrap}.guard-target-check{display:flex;align-items:center;gap:12px;min-width:0;flex:1;cursor:pointer}.target-name{display:grid;gap:3px;min-width:0}.target-error{font-size:11px;line-height:1.9;color:var(--muted);margin:12px 0;overflow-wrap:anywhere}.continuation-editor>summary{display:flex;justify-content:space-between;align-items:center;gap:12px;list-style:none;cursor:pointer;color:var(--accent);font-size:11px;padding-top:16px}.continuation-editor>summary>span{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.continuation-editor>summary>svg{transition:transform .2s}.continuation-editor[open]>summary>svg{transform:rotate(180deg)}.continuation-form{display:grid;gap:12px;margin-top:17px;border-top:1px solid var(--line);padding-top:17px}.resume-enabled{display:flex;align-items:center;gap:10px;font-size:12px;color:var(--text);line-height:1.8}.continuation-form>.field-label{display:flex;gap:9px;flex-wrap:wrap;justify-content:space-between;margin:3px 0 0}.continuation-form .resume-prompt{background:var(--surface);border-color:var(--line);color:var(--text);font-size:12px;padding:12px;min-height:95px}.rule-footer{display:flex;gap:14px;align-items:center;justify-content:space-between;flex-wrap:wrap}.rule-footer small{font-size:10px;color:var(--muted);line-height:1.9;flex:1;min-width:140px}.continuation-note{display:flex;align-items:flex-start;gap:7px;color:var(--muted);font-size:11px;line-height:1.9;margin-top:18px}.continuation-note svg{margin-top:3px}@media(max-width:700px){.conversation-search{flex-direction:column;gap:10px}.catalog-row{padding:12px;gap:10px}.catalog-title strong{font-size:11px}.catalog-row>.badge{font-size:9px}.catalog-actions>.button-row{width:100%;justify-content:flex-end}.continuation-card{padding:13px}.continuation-form>.field-label{font-size:11px}.rule-footer .btn{width:100%}.existing-conversations .section-heading{flex-wrap:wrap}}@media(prefers-reduced-motion:reduce){.catalog-row,.continuation-editor>summary>svg{transition:none}}
</style>
